<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject;

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class UserFederatedIdentityLoginProviderVO
{
    public static function from(UserFederatedIdentityLoginProviderVO|TenantLoginProviderRef $value): UserFederatedIdentityLoginProviderVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?UserFederatedIdentityLoginProviderVO
    {
        if ($value instanceof UserFederatedIdentityLoginProviderVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_a($value, TenantLoginProviderRef::class)) {
            return new UserFederatedIdentityLoginProviderVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['loginProvider'], [$value], ['TenantLoginProviderRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): UserFederatedIdentityLoginProviderVO
    {
        if ($value instanceof UserFederatedIdentityLoginProviderVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof UserFederatedIdentityLoginProviderVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly TenantLoginProviderRef $loginProvider
    ) {
    }
    public function value(): TenantLoginProviderRef
    {
        return $this->loginProvider;
    }
    public function equals(?UserFederatedIdentityLoginProviderVO $other): bool
    {
        return $this->value()->uid() == $other?->value()?->uid();
    }
}
